if(filter&&markers.length){const categories=new Set();markers.forEach(marker=>{marker.categories?.forEach(category=>{if(!categories.has(category.name)){filter.append($('<option>').text(category.name).val(category.name));categories.add(category.name)}})});if(categories.size){filter.on('change',event=>{const value=event.target.value;markers.forEach(marker=>{if(!value||(marker.categories?.some(category=>category.name===value)??!1)){marker.addTo(this.map)}else{marker.remove()}})})}else{filter.remove()}}
